us": "draft", "id": "41937485-b52b-5341-94b9-989eaefef2ec", "subject_id": "cac940ef-0d1d-54fc-af94-67f66714b456", "source_id": "6dfe8994-b802-52e9-bc37-f5b02bb4f0a4"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记安金全：安审琦之父亲。", "citation": "卷279·清泰二年（935；三月条下）·zztj-v279-y0935-p011·原文件第95行", "note": "原文：审琦，金全之子也。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "35b42cd5-bef9-53ca-9fe8-5d8a24807b51", "subject_id": "b52eca39-fd61-599b-8624-160fbb4ec282", "source_id": "6dfe8994-b802-52e9-bc37-f5b02bb4f0a4"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "安金全是安审琦的父亲。", "citation": "卷279·清泰二年（935；三月条下）·zztj-v279-y0935-p011·原文件第95行", "note": "原文：审琦，金全之子也。；核对说明：金全据安氏父名及旧安审琦传明同安北都护振武节度使，与已有人安金全同人；不混李金全。", "status": "draft", "id": "e3c81ec7-222d-511c-afee-575b4af22aac", "subject_id": "8e10bc4b-c015-592b-be27-a0d1abf05949", "source_id": "6dfe8994-b802-52e9-bc37-f5b02bb4f0a4"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧末帝纪同记壬戌安审琦领楚州顺化军节度使，彰圣军职如故，并列原富州刺史。", "citation": "《旧五代史》卷四十七，段落 jiu-wudaishi-205deb4a7860-p001293；EPUB电子本，纸本及异文待核", "note": "原文：壬戌，以左右彰聖都指揮使、富州刺史安審琦領楚州順化軍節度使，軍職如故。；核对说明：主省左右、富州、楚州及留军职，独立补充不改变主新职。", "status": "draft", "id": "c84d372e-0b03-5746-a7d0-6fccc43dc20f", "subject_id": "1769db99-75ee-5aa6-a44e-1d75b5f97895", "source_id": "23c407e1-3353-53ee-9015-1b416f0e621e"}, {"subject_table": "person", "field_path": "description", "claim_text": "旧安审琦传称其字国瑞，其先为沙陀部人。", "citation": "《旧五代史》卷123·安审琦传，段落 jiu-wudaishi-205deb4a7860-p002852；已核上下文及传主，纸本及异文待核。", "note": "原文：安審琦，字國瑞，其先沙陀部人也。；核对说明：已核卷123传首，祖先族属不能自动译成安本人出生于沙陀；不扩录同传晋汉周后事。", "status": "draft", "id": "3b959e40-3587-5242-ba93-90b37877aa87", "subject_id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa", "source_id": "7a247965-3223-5d80-8606-d946766fe120"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "旧安审琦传记其父金全任安北都护、振武军节度使。", "citation": "《旧五代史》卷123·安审琦传，段落 jiu-wudaishi-205deb4a7860-p002852；已核上下文及传主，纸本及异文待核。", "note": "原文：父金全，安北都護、振武軍節度使，累贈太師，《唐書》有傳。；核对说明：父名与旧军职核对已有安金全，不混同期李金全；累赠是身后官衔，不称935年父仍任官。", "status": "draft", "id": "f5e2f927-3f77-5279-a12a-090bc82f5bc0", "subject_id": "8e10bc4b-c015-592b-be27-a0d1abf05949", "source_id": "7a247965-3223-5d80-8606-d946766fe120"}]'::jsonb)
